using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class MorayPlacementRepair {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity";
 public static void Inspect(){EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();var actor=motion.actor;var root=actor.transform;var guard=actor.GetComponent<ReefAnimalClearance>();var body=actor.GetComponent<ReefSphereBody>();guard.RequiredHeight(root.position,root.rotation,out float height);Debug.Log("MORAY_START position="+root.position+" angles="+root.eulerAngles+" scale="+root.lossyScale+" sandRequired="+height+" envelope="+guard.animatedBody+" bodyClear="+body.Clear(root.position));foreach(var b in motion.animationPlayer.GetComponentsInChildren<Transform>().Where(t=>new[]{"Head","Jaw","Spine11","Root"}.Contains(t.name)))Debug.Log("MORAY_BONE "+b.name+" actorLocal="+root.InverseTransformPoint(b.position)+" meshLocal="+motion.animationPlayer.transform.InverseTransformPoint(b.position));foreach(var c in Physics.OverlapSphere(root.position,4,ReefSphereBody.SolidMask,QueryTriggerInteraction.Ignore).OrderBy(c=>Vector3.Distance(c.ClosestPoint(root.position),root.position)).Take(15))Debug.Log("MORAY_SOLID "+c.name+" center="+c.bounds.center+" size="+c.bounds.size+" closest="+c.ClosestPoint(root.position));YellowMorayIntegration.Capture();}
 static Mesh EyeMesh(){const string path="Assets/UnderwaterArt/TripoMoray/SocketEye.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);const int rings=10,segments=16;var v=new Vector3[(rings+1)*(segments+1)];var uv=new Vector2[v.Length];var triangles=new System.Collections.Generic.List<int>();for(int r=0;r<=rings;r++)for(int c=0;c<=segments;c++){float a=(float)r/rings*Mathf.PI,b=(float)c/segments*Mathf.PI*2;int i=r*(segments+1)+c;v[i]=new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Sin(a)*Mathf.Sin(b),-Mathf.Cos(a));uv[i]=new Vector2((float)c/segments,(float)r/rings);if(r<rings&&c<segments){triangles.AddRange(new[]{i,i+1,i+segments+1,i+1,i+segments+2,i+segments+1});}}var mesh=new Mesh{name="Socket-fitted moray eye",vertices=v,uv=uv,triangles=triangles.ToArray()};mesh.RecalculateNormals();mesh.RecalculateBounds();if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(saved);return saved;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static Material EyeMaterial(){const string folder="Assets/UnderwaterArt/TripoMoray/";var mat=AssetDatabase.LoadAssetAtPath<Material>(folder+"SocketEyes.mat");if(mat)return mat;var texture=new Texture2D(128,128,TextureFormat.RGB24,false);for(int y=0;y<128;y++)for(int x=0;x<128;x++){float z=-Mathf.Cos((y+.5f)/128*Mathf.PI),fiber=.5f+.5f*Mathf.Sin(x*1.86f);var color=z>.78f?new Color(.009f,.012f,.010f):z>.18f?new Color(.19f+fiber*.09f,.16f+fiber*.07f,.065f+fiber*.035f):new Color(.045f,.052f,.028f);texture.SetPixel(x,y,color);}texture.Apply();System.IO.File.WriteAllBytes(folder+"SocketEyes.png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(folder+"SocketEyes.png");mat=new Material(Shader.Find("Standard")){name="Moray socket eyes",mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"SocketEyes.png"),enableInstancing=true};mat.SetFloat("_Glossiness",.78f);AssetDatabase.CreateAsset(mat,folder+"SocketEyes.mat");return mat;}
 static void Eyes(YellowMorayMotion motion){var model=motion.animationPlayer.transform;motion.Clip("Idle").SampleAnimation(model.gameObject,0);var head=model.GetComponentsInChildren<Transform>().Single(b=>b.name=="Head");var mesh=EyeMesh();var mat=EyeMaterial();
  // Source socket coordinates in the retained Blender mesh; FBX maps (-x,z,-y).
  foreach(int side in new[]{-1,1}){string name=side<0?"Moray left eye":"Moray right eye";if(head.Find(name))continue;Vector3 socket=side<0?new Vector3(-.2044179f,-.4485366f,.0476194f):new Vector3(-.1771303f,-.4489453f,.0586407f);Vector3 n=(new Vector3(side,0,0)*.85f+new Vector3(0,-.05f,.1f)).normalized;var local=new Vector3(-socket.x,socket.z,-socket.y);var normal=new Vector3(-n.x,n.z,-n.y);var eye=new GameObject(name);eye.transform.SetParent(head,false);eye.transform.position=model.TransformPoint(local);eye.transform.rotation=Quaternion.LookRotation(model.TransformDirection(normal),model.up);float scale=model.lossyScale.x;eye.transform.localScale=Vector3.one;eye.transform.localScale=new Vector3(.0062f*scale/eye.transform.lossyScale.x,.0062f*scale/eye.transform.lossyScale.y,.005f*scale/eye.transform.lossyScale.z);eye.AddComponent<MeshFilter>().sharedMesh=mesh;var r=eye.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;Debug.Log("MORAY_SOCKET_EYE "+name+" world="+eye.transform.position);}
 }
 public static void Run(){var scene=EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();var actor=motion.actor;var root=actor.transform;Eyes(motion);var guard=actor.GetComponent<ReefAnimalClearance>();guard.animatedBody=AnimalSeabedRepair.Envelope(root);var wreck=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Single(t=>t.name=="Coral colonized timber wreck"&&Mathf.Abs(t.position.z-64)<10);var body=actor.GetComponent<ReefSphereBody>();var old=root.position;var oldRotation=root.rotation;
  var skin=motion.animationPlayer.GetComponentInChildren<SkinnedMeshRenderer>();var samples=new System.Collections.Generic.List<Vector3>();foreach(var state in new[]{"Idle","React","Retreat","Recover","Swim"})for(int phase=0;phase<3;phase++){motion.Clip(state).SampleAnimation(motion.animationPlayer.gameObject,motion.Clip(state).length*phase/3);var points=OctopusRepairValidation.Points(skin);for(int i=0;i<points.Length;i+=80)samples.Add(root.InverseTransformPoint(points[i]));}motion.Clip("Idle").SampleAnimation(motion.animationPlayer.gameObject,0);
  bool placed=false;float best=float.PositiveInfinity;Vector3 chosen=old;Quaternion chosenRotation=oldRotation;
  foreach(float x in new[]{1.4f,1.7f,1.1f,2f})foreach(float z in new[]{7.2f,7.6f,6.8f})for(float y=1.3f;y<=2.9f;y+=.12f){var target=wreck.TransformPoint(new Vector3(x,y,z));var direction=wreck.TransformDirection(new Vector3(-.3f,0,1));direction.y=0;var rotation=Quaternion.LookRotation(direction);root.SetPositionAndRotation(target,rotation);guard.Enforce();target=root.position;if(!body.Clear(target)||!body.Clear(target-root.forward*.65f))continue;bool clear=true;foreach(float retreat in new[]{0f,.65f}){foreach(var p in samples){var world=root.TransformPoint(p)-root.forward*retreat;if(Physics.CheckSphere(world,.012f,ReefSphereBody.SolidMask,QueryTriggerInteraction.Ignore)){clear=false;break;}}if(!clear)break;}if(!clear)continue;float score=(target-old).sqrMagnitude+Mathf.Max(0,y-1.3f)*.7f;if(score<best){best=score;chosen=target;chosenRotation=rotation;placed=true;}}
  if(!placed){root.SetPositionAndRotation(old,oldRotation);throw new Exception("No safe stern-opening placement found; scene not saved");}root.SetPositionAndRotation(chosen,chosenRotation);guard.Enforce();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var clone=UnityEngine.Object.Instantiate(actor.gameObject);clone.transform.position=Vector3.zero;PrefabUtility.SaveAsPrefabAsset(clone,"Assets/UnderwaterArt/TripoMoray/TripoMorayEncounter.prefab");UnityEngine.Object.DestroyImmediate(clone);Debug.Log("MORAY_PLACEMENT_REPAIRED from="+old+" to="+root.position+" rotation="+root.eulerAngles+" sampledClearancePoints="+samples.Count);
  Validate();Capture();
 }
 public static void Validate(){EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();var actor=motion.actor;var head=motion.animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="Head");var eyes=new[]{head.Find("Moray left eye"),head.Find("Moray right eye")};if(eyes.Any(e=>!e||!e.GetComponent<Renderer>().enabled))throw new Exception("Missing eye");var locals=eyes.Select(e=>e.localPosition).ToArray();var guard=actor.GetComponent<ReefAnimalClearance>();int checks=0;foreach(string name in new[]{"Idle","React","Retreat","Recover","Swim"})for(int i=0;i<=32;i++){motion.Clip(name).SampleAnimation(motion.animationPlayer.gameObject,motion.Clip(name).length*i/32);for(int eye=0;eye<2;eye++){if(Vector3.Distance(locals[eye],eyes[eye].localPosition)>.00001f)throw new Exception("Eye detached");foreach(var v in eyes[eye].GetComponent<MeshFilter>().sharedMesh.vertices){var p=actor.transform.InverseTransformPoint(eyes[eye].TransformPoint(v));if(!guard.animatedBody.Contains(p))throw new Exception("Eye outside sand envelope");checks++;}}}motion.Clip("Idle").SampleAnimation(motion.animationPlayer.gameObject,0);actor.Initialize();var home=actor.transform.position;actor.React();for(int i=0;i<360;i++){actor.Step(1f/30);motion.Step(1f/30);guard.Enforce();if(!guard.RequiredHeight(actor.transform.position,actor.transform.rotation,out float floor)||actor.transform.position.y<floor-.0001f)throw new Exception("Moray entered sand");}if(Vector3.Distance(home,actor.transform.position)>.08f)throw new Exception("Moray did not recover");Debug.Log("MORAY_EYES_AND_POSITION_VALIDATED eyeVertexChecks="+checks+" clips=5 retreatRecovery=true");}
 public static void Capture(){EditorSceneManager.OpenScene(Scene);var motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();var actor=motion.actor;motion.Clip("Idle").SampleAnimation(motion.animationPlayer.gameObject,0);System.IO.Directory.CreateDirectory("Renders/MorayRepair");YellowMorayIntegration.Capture();System.IO.File.Copy("Renders/YellowMorayUnity/WreckMoray.png","Renders/MorayRepair/Context.png",true);motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();actor=motion.actor;var head=motion.animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="Head");var eye=head.Find("Moray left eye");var center=(eye.position+head.Find("Moray right eye").position)*.5f;var camera=Camera.main;RenderSettings.fog=false;RenderSettings.ambientLight=new Color(.5f,.55f,.6f);foreach(int side in new[]{-1,1}){camera.transform.position=center+actor.transform.right*side*.55f+actor.transform.forward*.3f+Vector3.up*.12f;camera.transform.LookAt(center);camera.fieldOfView=38;ReefCorrectionAudit.Capture(camera,"Renders/MorayRepair/"+(side<0?"Left":"Right")+".png");}}
 public static void RefitEyes(){var scene=EditorSceneManager.OpenScene(Scene);var motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();var head=motion.animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="Head");foreach(string name in new[]{"Moray left eye","Moray right eye"}){var eye=head.Find(name);if(eye)UnityEngine.Object.DestroyImmediate(eye.gameObject);}Eyes(motion);var guard=motion.actor.GetComponent<ReefAnimalClearance>();guard.animatedBody=AnimalSeabedRepair.Envelope(motion.actor.transform);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var clone=UnityEngine.Object.Instantiate(motion.actor.gameObject);clone.transform.position=Vector3.zero;PrefabUtility.SaveAsPrefabAsset(clone,"Assets/UnderwaterArt/TripoMoray/TripoMorayEncounter.prefab");UnityEngine.Object.DestroyImmediate(clone);Validate();Capture();}
 public static void FitRenderedSockets(){var scene=EditorSceneManager.OpenScene(Scene);var motion=UnityEngine.Object.FindFirstObjectByType<YellowMorayMotion>();motion.Clip("Idle").SampleAnimation(motion.animationPlayer.gameObject,.5f);var actor=motion.actor;var head=motion.animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="Head");var eyes=new[]{head.Find("Moray left eye"),head.Find("Moray right eye")};var center=(eyes[0].position+eyes[1].position)*.5f;var camera=new GameObject("Moray socket fitting camera").AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.aspect=1.4f;camera.fieldOfView=38;var vertices=OctopusRepairValidation.Points(motion.animationPlayer.GetComponentInChildren<SkinnedMeshRenderer>());
  foreach(int side in new[]{-1,1}){camera.transform.position=center+actor.transform.right*side*.55f+actor.transform.forward*.3f+Vector3.up*.12f;camera.transform.LookAt(center);var eye=eyes.OrderBy(e=>Vector3.Distance(e.position,camera.transform.position)).First();var pixel=side<0?new Vector2(725,455):new Vector2(688,540);var target=new Vector2(pixel.x/1400,1-pixel.y/1000);float depth=camera.WorldToViewportPoint(eye.position).z;var ring=vertices.Select(v=>new{world=v,screen=camera.WorldToViewportPoint(v)}).Where(v=>Mathf.Abs(v.screen.z-depth)<.045f).OrderBy(v=>(new Vector2((v.screen.x-target.x)*1400,(v.screen.y-target.y)*1000)).sqrMagnitude).Take(20).ToArray();if(ring.Length<20)throw new Exception("Socket rim missing");float rimDepth=ring.Average(v=>v.screen.z);var ray=camera.ViewportPointToRay(new Vector3(target.x,target.y,0));float along=(rimDepth-camera.nearClipPlane)/Vector3.Dot(ray.direction,camera.transform.forward);eye.position=ray.GetPoint(along);var local=motion.animationPlayer.transform.InverseTransformPoint(eye.position);Debug.Log("MORAY_FITTED_SOCKET "+eye.name+" model="+local.ToString("F7"));}
  UnityEngine.Object.DestroyImmediate(camera.gameObject);motion.Clip("Idle").SampleAnimation(motion.animationPlayer.gameObject,0);var guard=actor.GetComponent<ReefAnimalClearance>();guard.animatedBody=AnimalSeabedRepair.Envelope(actor.transform);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var clone=UnityEngine.Object.Instantiate(actor.gameObject);clone.transform.position=Vector3.zero;PrefabUtility.SaveAsPrefabAsset(clone,"Assets/UnderwaterArt/TripoMoray/TripoMorayEncounter.prefab");UnityEngine.Object.DestroyImmediate(clone);Validate();Capture();}
}}